        <a href="cart.html">购物车</a>
    </nav>
</header>
<main>
    <div class="image">
        <img src="images/blouse.jpg" alt="简约衬衫">
    </div>
    <div class="info">
        <h2>简约衬衫</h2>
        <p>这款简约衬衫采用柔软面料，适合职场与日常休闲场合，经典百搭。</p>
        <div class="price">￥199</div>
        <div class="size">
            <label for="sizeSelect">尺码：</label>
            <select id="sizeSelect">
                <option value="S">S</option>
                <option value="M">M</option>
                <option value="L">L</option>
                <option value="XL">XL</option>
            </select>
        </div>
        <div class="qty">
            <label for="qtyInput">数量：</label>
            <input type="number" id="qtyInput" value="1" min="1" style="width:60px;">
        </div>
        <button id="addToCart">加入购物车</button>
    </div>
</main>
<footer>
    © 2026 可衣. 版权所有
</footer>
<script>
    function addToCart() {
        const product = {
            id: 'product1',
            name: '简约衬衫',
            size: document.getElementById('sizeSelect').value,
            price: 199,
            qty: parseInt(document.getElementById('qtyInput').value, 10)
        };
        let cart = JSON.parse(localStorage.getItem('cart') || '[]');
        const index = cart.findIndex(item => item.id === product.id && item.size === product.size);
        if (index > -1) {
            cart[index].qty += product.qty;
        } else {
            cart.push(product);
        }
        localStorage.setItem('cart', JSON.stringify(cart));
        alert('已加入购物车');
    }
    document.getElementById('addToCart').addEventListener('click', addToCart);
</script>
</body>
</html>
