        footer{background:#fff;padding:20px;text-align:center;border-top:1px solid #ddd;margin-top:40px;}
        @media(max-width:600px){
            table,thead,tbody,tr,td,th{display:block;}
            tr{margin-bottom:20px;}
            td{padding-left:50%;position:relative;}
            td::before{content:attr(data-label);position:absolute;left:10px;font-weight:600;}
        }
    </style>
</head>
<body>
<header>
    <h1>可衣</h1>
    <nav>
        <a href="index.html">首页</a>
        <a href="product-list.html">商品</a>
        <a href="cart.html">购物车</a>
    </nav>
</header>
<main>
    <h2>购物车</h2>
    <div id="cartContainer">
        <p>加载中...</p>
    </div>
</main>
<footer>
    © 2026 可衣. 版权所有
</footer>
<script>
    function loadCart() {
        const cart = JSON.parse(localStorage.getItem('cart') || '[]');
        const container = document.getElementById('cartContainer');
        if (cart.length === 0) {
            container.innerHTML = '<p>购物车为空。</p>';
            return;
        }
        let table = '<table><thead><tr><th>商品</th><th>尺码</th><th>单价</th><th>数量</th><th>小计</th><th>操作</th></tr></thead><tbody>';
        let total = 0;
        cart.forEach((item, index) => {
            const subtotal = item.price * item.qty;
            total += subtotal;
            table += `<tr>
                <td data-label="商品">${item.name}</td>
                <td data-label="尺码">${item.size}</td>
                <td data-label="单价">￥${item.price}</td>
                <td data-label="数量"><input type="number" class="qty-input" value="${item.qty}" min="1" data-index="${index}"></td>
                <td data-label="小计">￥${subtotal}</td>
                <td data-label="操作"><button class="remove-btn" data-index="${index}">删除</button></td>
            </tr>`;
        });
        table += '</tbody></table>';
        table += `<div class="total">总计：￥${total}</div>`;
        table += `<button class="checkout">去结算</button>`;
        container.innerHTML = table;
        document.querySelectorAll('.qty-input').forEach(input => {
            input.addEventListener('change', updateQty);
        });
        document.querySelectorAll('.remove-btn').forEach(btn => {
            btn.addEventListener('click', removeItem);
        });
    }
    function updateQty(e) {
        const index = e.target.dataset.index;
        const newQty = parseInt(e.target.value, 10);
        if (newQty < 1) {
            e.target.value = 1;
            return;
        }
        const cart = JSON.parse(localStorage.getItem('cart') || '[]');
        cart[index].qty = newQty;
        localStorage.setItem('cart', JSON.stringify(cart));
        loadCart();
    }
    function removeItem(e) {
        const index = e.target.dataset.index;
        const cart = JSON.parse(localStorage.getItem('cart') || '[]');
        cart.splice(index, 1);
        localStorage.setItem('cart', JSON.stringify(cart));
        loadCart();
    }
    window.addEventListener('DOMContentLoaded', loadCart);
</script>
</body>
</html>
